     1→import { useState, useCallback, useMemo } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import {
    13→  Page,
    14→  Layout,
    15→  Card,
    16→  BlockStack,
    17→  InlineStack,
    18→  Text,
    19→  Button,
    20→  TextField,
    21→  Select,
    22→  Modal,
    23→  DataTable,
    24→  EmptyState,
    25→  Divider,
    26→  Box,
    27→  Tooltip,
    28→  Icon,
    29→  Banner,
    30→  Pagination,
    31→  InlineGrid,
    32→} from "@shopify/polaris";
    33→import {
    34→  SearchIcon,
    35→  DeleteIcon,
    36→  PlusIcon,
    37→  EmailIcon,
    38→} from "@shopify/polaris-icons";
    39→
    40→const PAGE_SIZE = 10;
    41→
    42→export const loader = async ({ request }: LoaderFunctionArgs) => {
    43→  const { session } = await authenticate.admin(request);
    44→  const shop = session.shop;
    45→
    46→  const entries = await db.waitlistEntry.findMany({
    47→    where: { shop },
    48→    orderBy: { createdAt: "desc" },
    49→  });
    50→
    51→  const stats = {
    52→    total: entries.length,
    53→    waiting: entries.filter((e) => e.status === "waiting").length,
    54→    notified: entries.filter((e) => e.status === "notified").length,
    55→    converted: entries.filter((e) => e.status === "converted").length,
    56→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
    57→  };
    58→
    59→  return { entries, stats };
    60→};
    61→
    62→export const action = async ({ request }: ActionFunctionArgs) => {
    63→  const { session } = await authenticate.admin(request);
    64→  const shop = session.shop;
    65→  const formData = await request.formData();
    66→  const intent = formData.get("intent");
    67→
    68→  if (intent === "add") {
    69→    const email = String(formData.get("email") || "").trim().toLowerCase();
    70→    const zipCode = String(formData.get("zipCode") || "")
    71→      .trim()
    72→      .toUpperCase();
    73→    const note = String(formData.get("note") || "").trim() || null;
    74→
    75→    if (!email || !zipCode) return { error: "Email and zip code are required." };
    76→
    77→    try {
    78→      await db.waitlistEntry.create({
    79→        data: { shop, email, zipCode, note },
    80→      });
    81→      return { success: true, action: "added" };
    82→    } catch {
    83→      return { error: "This email is already on the waitlist for this zip code." };
    84→    }
    85→  }
    86→
    87→  if (intent === "delete") {
    88→    const id = String(formData.get("id"));
    89→    await db.waitlistEntry.delete({ where: { id } });
    90→    return { success: true, action: "deleted" };
    91→  }
    92→
    93→  if (intent === "update-status") {
    94→    const id = String(formData.get("id"));
    95→    const status = String(formData.get("status"));
    96→    await db.waitlistEntry.update({ where: { id }, data: { status } });
    97→    return { success: true, action: "updated" };
    98→  }
    99→
   100→  if (intent === "bulk-notify") {
   101→    const zipCode = String(formData.get("zipCode") || "")
   102→      .trim()
   103→      .toUpperCase();
   104→    if (!zipCode) return { error: "Zip code is required." };
   105→
   106→    const updated = await db.waitlistEntry.updateMany({
   107→      where: { shop, zipCode, status: "waiting" },
   108→      data: { status: "notified" },
   109→    });
   110→
   111→    return {
   112→      success: true,
   113→      action: "bulk-notify",
   114→      count: updated.count,
   115→      zipCode,
   116→    };
   117→  }
   118→
   119→  if (intent === "delete-all-notified") {
   120→    const deleted = await db.waitlistEntry.deleteMany({
   121→      where: { shop, status: "notified" },
   122→    });
   123→    return { success: true, action: "deleted-notified", count: deleted.count };
   124→  }
   125→
   126→  return null;
   127→};
   128→
   129→type WaitlistEntry = {
   130→  id: string;
   131→  email: string;
   132→  zipCode: string;
   133→  note: string | null;
   134→  status: string;
   135→  createdAt: string | Date;
   136→};
   137→
   138→export default function WaitlistPage() {
   139→  const { entries, stats } = useLoaderData<typeof loader>();
   140→  const fetcher = useFetcher<typeof action>();
   141→  const shopify = useAppBridge();
   142→  const navigate = useNavigate();
   143→
   144→  const [searchQuery, setSearchQuery] = useState("");
   145→  const [statusFilter, setStatusFilter] = useState("all");
   146→  const [currentPage, setCurrentPage] = useState(1);
   147→  const [addModalOpen, setAddModalOpen] = useState(false);
   148→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
   149→
   150→  // Form state
   151→  const [newEmail, setNewEmail] = useState("");
   152→  const [newZipCode, setNewZipCode] = useState("");
   153→  const [newNote, setNewNote] = useState("");
   154→  const [notifyZip, setNotifyZip] = useState("");
   155→
   156→  const actionError =
   157→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   158→  const bulkResult =
   159→    fetcher.data && "action" in fetcher.data && fetcher.data.action === "bulk-notify"
   160→      ? fetcher.data
   161→      : null;
   162→
   163→  const filteredEntries = useMemo(() => {
   164→    let filtered = entries as WaitlistEntry[];
   165→    if (searchQuery.trim()) {
   166→      const q = searchQuery.trim().toLowerCase();
   167→      filtered = filtered.filter(
   168→        (e) =>
   169→          e.email.toLowerCase().includes(q) ||
   170→          e.zipCode.toLowerCase().includes(q) ||
   171→          (e.note && e.note.toLowerCase().includes(q)),
   172→      );
   173→    }
   174→    if (statusFilter !== "all") {
   175→      filtered = filtered.filter((e) => e.status === statusFilter);
   176→    }
   177→    return filtered;
   178→  }, [entries, searchQuery, statusFilter]);
   179→
   180→  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
   181→  const paginatedEntries = useMemo(() => {
   182→    const start = (currentPage - 1) * PAGE_SIZE;
   183→    return filteredEntries.slice(start, start + PAGE_SIZE);
   184→  }, [filteredEntries, currentPage]);
   185→
   186→  const handleSearchChange = useCallback((val: string) => {
   187→    setSearchQuery(val);
   188→    setCurrentPage(1);
   189→  }, []);
   190→
   191→  const handleFilterChange = useCallback((val: string) => {
   192→    setStatusFilter(val);
   193→    setCurrentPage(1);
   194→  }, []);
   195→
   196→  const handleAdd = useCallback(() => {
   197→    if (!newEmail.trim() || !newZipCode.trim()) return;
   198→    const fd = new FormData();
   199→    fd.set("intent", "add");
   200→    fd.set("email", newEmail);
   201→    fd.set("zipCode", newZipCode);
   202→    fd.set("note", newNote);
   203→    fetcher.submit(fd, { method: "POST" });
   204→    setNewEmail("");
   205→    setNewZipCode("");
   206→    setNewNote("");
   207→    setAddModalOpen(false);
   208→    shopify.toast.show("Added to waitlist");
   209→  }, [newEmail, newZipCode, newNote, fetcher, shopify]);
   210→
   211→  const handleDelete = useCallback(
   212→    (id: string) => {
   213→      const fd = new FormData();
   214→      fd.set("intent", "delete");
   215→      fd.set("id", id);
   216→      fetcher.submit(fd, { method: "POST" });
   217→      shopify.toast.show("Entry removed");
   218→    },
   219→    [fetcher, shopify],
   220→  );
   221→
   222→  const handleStatusChange = useCallback(
   223→    (id: string, status: string) => {
   224→      const fd = new FormData();
   225→      fd.set("intent", "update-status");
   226→      fd.set("id", id);
   227→      fd.set("status", status);
   228→      fetcher.submit(fd, { method: "POST" });
   229→    },
   230→    [fetcher],
   231→  );
   232→
   233→  const handleBulkNotify = useCallback(() => {
   234→    if (!notifyZip.trim()) return;
   235→    const fd = new FormData();
   236→    fd.set("intent", "bulk-notify");
   237→    fd.set("zipCode", notifyZip);
   238→    fetcher.submit(fd, { method: "POST" });
   239→    setNotifyModalOpen(false);
   240→    setNotifyZip("");
   241→    shopify.toast.show("Customers marked as notified");
   242→  }, [notifyZip, fetcher, shopify]);
   243→
   244→  const handleDeleteNotified = useCallback(() => {
   245→    const fd = new FormData();
   246→    fd.set("intent", "delete-all-notified");
   247→    fetcher.submit(fd, { method: "POST" });
   248→    shopify.toast.show("Notified entries cleared");
   249→  }, [fetcher, shopify]);
   250→
   251→  const statusOptions = [
   252→    { label: "Waiting", value: "waiting" },
   253→    { label: "Notified", value: "notified" },
   254→    { label: "Converted", value: "converted" },
   255→  ];
   256→
   257→  const filterOptions = [
   258→    { label: "All", value: "all" },
   259→    { label: "Waiting", value: "waiting" },
   260→    { label: "Notified", value: "notified" },
   261→    { label: "Converted", value: "converted" },
   262→  ];
   263→
   264→  const formatDate = (d: string | Date) => {
   265→    const date = new Date(d);
   266→    return date.toLocaleDateString("en-US", {
   267→      month: "short",
   268→      day: "numeric",
   269→      year: "numeric",
   270→    });
   271→  };
   272→
   273→  const tableRows = paginatedEntries.map((entry) => [
   274→    <Text as="span" fontWeight="semibold" key={`email-${entry.id}`}>
   275→      {entry.email}
   276→    </Text>,
   277→    <Text as="span" fontWeight="bold" key={`zip-${entry.id}`}>
   278→      {entry.zipCode}
   279→    </Text>,
   280→    <div key={`status-${entry.id}`} style={{ minWidth: "120px" }}>
   281→      <Select
   282→        label="Status"
   283→        labelHidden
   284→        options={statusOptions}
   285→        value={entry.status}
   286→        onChange={(val) => handleStatusChange(entry.id, val)}
   287→      />
   288→    </div>,
   289→    entry.note || (
   290→      <Text as="span" tone="subdued">
   291→        —
   292→      </Text>
   293→    ),
   294→    formatDate(entry.createdAt),
   295→    <Tooltip content="Remove from waitlist" key={`del-${entry.id}`}>
   296→      <Button
   297→        size="slim"
   298→        variant="tertiary"
   299→        tone="critical"
   300→        onClick={() => handleDelete(entry.id)}
   301→        icon={DeleteIcon}
   302→        accessibilityLabel="Delete"
   303→      />
   304→    </Tooltip>,
   305→  ]);
   306→
   307→  return (
   308→    <Page
   309→      title="Customer Waitlist"
   310→      subtitle="Customers waiting for delivery availability in their area"
   311→      backAction={{ onAction: () => navigate("/app") }}
   312→      primaryAction={{
   313→        content: "Add Entry",
   314→        icon: PlusIcon,
   315→        onAction: () => setAddModalOpen(true),
   316→      }}
   317→      secondaryActions={[
   318→        {
   319→          content: "Notify by Zip",
   320→          icon: EmailIcon,
   321→          onAction: () => setNotifyModalOpen(true),
   322→        },
   323→      ]}
   324→    >
   325→      <Box paddingBlockEnd="1600">
   326→      <Layout>
   327→        {/* Stats */}
   328→        <Layout.Section>
   329→          <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
   330→            <Box
   331→              padding="400"
   332→              background="bg-surface"
   333→              borderWidth="025"
   334→              borderColor="border"
   335→              borderRadius="200"
   336→            >
   337→              <BlockStack gap="100">
   338→                <Text as="p" tone="subdued" variant="bodySm">
   339→                  Total
   340→                </Text>
   341→                <Text as="p" variant="headingXl" fontWeight="bold">
   342→                  {stats.total}
   343→                </Text>
   344→              </BlockStack>
   345→            </Box>
   346→            <Box
   347→              padding="400"
   348→              background="bg-surface-warning"
   349→              borderWidth="025"
   350→              borderColor="border-warning"
   351→              borderRadius="200"
   352→            >
   353→              <BlockStack gap="100">
   354→                <Text as="p" tone="caution" variant="bodySm">
   355→                  Waiting
   356→                </Text>
   357→                <Text as="p" variant="headingXl" fontWeight="bold" tone="caution">
   358→                  {stats.waiting}
   359→                </Text>
   360→              </BlockStack>
   361→            </Box>
   362→            <Box
   363→              padding="400"
   364→              background="bg-surface-info"
   365→              borderWidth="025"
   366→              borderColor="border-info"
   367→              borderRadius="200"
   368→            >
   369→              <BlockStack gap="100">
   370→                <Text as="p" tone="subdued" variant="bodySm">
   371→                  Notified
   372→                </Text>
   373→                <Text as="p" variant="headingXl" fontWeight="bold">
   374→                  {stats.notified}
   375→                </Text>
   376→              </BlockStack>
   377→            </Box>
   378→            <Box
   379→              padding="400"
   380→              background="bg-surface-success"
   381→              borderWidth="025"
   382→              borderColor="border-success"
   383→              borderRadius="200"
   384→            >
   385→              <BlockStack gap="100">
   386→                <Text as="p" tone="success" variant="bodySm">
   387→                  Converted
   388→                </Text>
   389→                <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
   390→                  {stats.converted}
   391→                </Text>
   392→              </BlockStack>
   393→            </Box>
   394→            <Box
   395→              padding="400"
   396→              background="bg-surface"
   397→              borderWidth="025"
   398→              borderColor="border"
   399→              borderRadius="200"
   400→            >
   401→              <BlockStack gap="100">
   402→                <Text as="p" tone="subdued" variant="bodySm">
   403→                  Unique Zips
   404→                </Text>
   405→                <Text as="p" variant="headingXl" fontWeight="bold">
   406→                  {stats.uniqueZips}
   407→                </Text>
   408→              </BlockStack>
   409→            </Box>
   410→          </InlineGrid>
   411→        </Layout.Section>
   412→
   413→        {/* Waitlist Table */}
   414→        <Layout.Section>
   415→          <Card padding="0">
   416→            <Box padding="400">
   417→              <InlineStack
   418→                gap="300"
   419→                align="space-between"
   420→                blockAlign="center"
   421→                wrap
   422→              >
   423→                <InlineStack gap="300" blockAlign="center" wrap>
   424→                  <div style={{ minWidth: "260px" }}>
   425→                    <TextField
   426→                      label="Search"
   427→                      labelHidden
   428→                      value={searchQuery}
   429→                      onChange={handleSearchChange}
   430→                      placeholder="Search by email or zip code..."
   431→                      autoComplete="off"
   432→                      prefix={<Icon source={SearchIcon} />}
   433→                      clearButton
   434→                      onClearButtonClick={() => handleSearchChange("")}
   435→                    />
   436→                  </div>
   437→                  <div style={{ minWidth: "120px" }}>
   438→                    <Select
   439→                      label="Status"
   440→                      labelHidden
   441→                      options={filterOptions}
   442→                      value={statusFilter}
   443→                      onChange={handleFilterChange}
   444→                    />
   445→                  </div>
   446→                </InlineStack>
   447→                <InlineStack gap="200">
   448→                  {stats.notified > 0 && (
   449→                    <Button
   450→                      tone="critical"
   451→                      variant="plain"
   452→                      onClick={handleDeleteNotified}
   453→                    >
   454→                      {`Clear notified (${stats.notified})`}
   455→                    </Button>
   456→                  )}
   457→                  <Button
   458→                    variant="primary"
   459→                    icon={PlusIcon}
   460→                    onClick={() => setAddModalOpen(true)}
   461→                  >
   462→                    Add Entry
   463→                  </Button>
   464→                </InlineStack>
   465→              </InlineStack>
   466→            </Box>
   467→            <Divider />
   468→
   469→            {(entries as WaitlistEntry[]).length === 0 ? (
   470→              <EmptyState
   471→                heading="No customers on the waitlist yet"
   472→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
   473→                action={{
   474→                  content: "Add first entry",
   475→                  onAction: () => setAddModalOpen(true),
   476→                }}
   477→              >
   478→                <p>
   479→                  When customers enter a zip code that isn&apos;t in your delivery
   480→                  area, they can join the waitlist. You can also manually add
   481→                  entries here. Enable the waitlist on blocked zip codes in your
   482→                  Widget settings.
   483→                </p>
   484→              </EmptyState>
   485→            ) : filteredEntries.length === 0 ? (
   486→              <Box padding="600">
   487→                <BlockStack gap="200" inlineAlign="center">
   488→                  <Text as="p" tone="subdued" alignment="center">
   489→                    No entries match your search.
   490→                  </Text>
   491→                  <Button
   492→                    variant="plain"
   493→                    onClick={() => {
   494→                      setSearchQuery("");
   495→                      setStatusFilter("all");
   496→                    }}
   497→                  >
   498→                    Clear filters
   499→                  </Button>
   500→                </BlockStack>
   501→              </Box>
   502→            ) : (
   503→              <>
   504→                <DataTable
   505→                  columnContentTypes={[
   506→                    "text",
   507→                    "text",
   508→                    "text",
   509→                    "text",
   510→                    "text",
   511→                    "text",
   512→                  ]}
   513→                  headings={[
   514→                    "Email",
   515→                    "Zip Code",
   516→                    "Status",
   517→                    "Note",
   518→                    "Date",
   519→                    "Actions",
   520→                  ]}
   521→                  rows={tableRows}
   522→                  hoverable
   523→                />
   524→                {totalPages > 1 && (
   525→                  <Box padding="400">
   526→                    <InlineStack align="center" blockAlign="center" gap="300">
   527→                      <Pagination
   528→                        hasPrevious={currentPage > 1}
   529→                        onPrevious={() =>
   530→                          setCurrentPage((p) => Math.max(1, p - 1))
   531→                        }
   532→                        hasNext={currentPage < totalPages}
   533→                        onNext={() =>
   534→                          setCurrentPage((p) => Math.min(totalPages, p + 1))
   535→                        }
   536→                      />
   537→                      <Text as="span" tone="subdued" variant="bodySm">
   538→                        Page {currentPage} of {totalPages} (
   539→                        {filteredEntries.length} results)
   540→                      </Text>
   541→                    </InlineStack>
   542→                  </Box>
   543→                )}
   544→              </>
   545→            )}
   546→          </Card>
   547→        </Layout.Section>
   548→      </Layout>
   549→      </Box>
   550→
   551→      {/* Add Entry Modal */}
   552→      <Modal
   553→        open={addModalOpen}
   554→        onClose={() => {
   555→          setAddModalOpen(false);
   556→          setNewEmail("");
   557→          setNewZipCode("");
   558→          setNewNote("");
   559→        }}
   560→        title="Add Waitlist Entry"
   561→        primaryAction={{ content: "Add to Waitlist", onAction: handleAdd }}
   562→        secondaryActions={[
   563→          {
   564→            content: "Cancel",
   565→            onAction: () => {
   566→              setAddModalOpen(false);
   567→              setNewEmail("");
   568→              setNewZipCode("");
   569→              setNewNote("");
   570→            },
   571→          },
   572→        ]}
   573→      >
   574→        <Modal.Section>
   575→          <BlockStack gap="400">
   576→            {actionError && <Banner tone="critical">{actionError}</Banner>}
   577→            <TextField
   578→              label="Email"
   579→              type="email"
   580→              value={newEmail}
   581→              onChange={setNewEmail}
   582→              placeholder="customer@example.com"
   583→              autoComplete="off"
   584→            />
   585→            <TextField
   586→              label="Zip Code"
   587→              value={newZipCode}
   588→              onChange={setNewZipCode}
   589→              placeholder="e.g. 33101"
   590→              autoComplete="off"
   591→            />
   592→            <TextField
   593→              label="Note (optional)"
   594→              value={newNote}
   595→              onChange={setNewNote}
   596→              placeholder="Any additional notes..."
   597→              autoComplete="off"
   598→              multiline={2}
   599→            />
   600→          </BlockStack>
   601→        </Modal.Section>
   602→      </Modal>
   603→
   604→      {/* Bulk Notify Modal */}
   605→      <Modal
   606→        open={notifyModalOpen}
   607→        onClose={() => {
   608→          setNotifyModalOpen(false);
   609→          setNotifyZip("");
   610→        }}
   611→        title="Notify Waitlist by Zip Code"
   612→        primaryAction={{
   613→          content: "Mark as Notified",
   614→          onAction: handleBulkNotify,
   615→        }}
   616→        secondaryActions={[
   617→          {
   618→            content: "Cancel",
   619→            onAction: () => {
   620→              setNotifyModalOpen(false);
   621→              setNotifyZip("");
   622→            },
   623→          },
   624→        ]}
   625→      >
   626→        <Modal.Section>
   627→          <BlockStack gap="400">
   628→            {bulkResult && (
   629→              <Banner tone="success">
   630→                Marked {bulkResult.count as number} customers as notified for
   631→                zip code {bulkResult.zipCode as string}.
   632→              </Banner>
   633→            )}
   634→            <Text as="p">
   635→              Enter a zip code to mark all waiting customers for that area as
   636→              &quot;Notified&quot;. Use this when you&apos;ve expanded delivery to a new area
   637→              and want to let waitlisted customers know.
   638→            </Text>
   639→            <TextField
   640→              label="Zip Code"
   641→              value={notifyZip}
   642→              onChange={setNotifyZip}
   643→              placeholder="e.g. 33101"
   644→              autoComplete="off"
   645→            />
   646→          </BlockStack>
   647→        </Modal.Section>
   648→      </Modal>
   649→    </Page>
   650→  );
   651→}
   652→
   653→export const headers: HeadersFunction = (headersArgs) => {
   654→  return boundary.headers(headersArgs);
   655→};
